function fit(cv){const r=cv.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);cv.width=Math.max(1,r.width*d);cv.height=Math.max(1,r.height*d);const c=cv.getContext('2d');c.setTransform(d,0,0,d,0,0);return[c,r.width,r.height]}
const FONT='11px Sora,Vazirmatn,sans-serif';
function lineChart(cv,series,o={}){if(!cv||!cv.isConnected)return;const[c,w,h]=fit(cv),mu=css(cv,'--mu')||'#98a2bd';c.clearRect(0,0,w,h);const pl=40,pb=22,pt=8,pr=10,iw=w-pl-pr,ih=h-pt-pb,max=o.max||100;c.font=FONT;c.fillStyle=mu;c.strokeStyle='rgba(128,140,190,.18)';
 for(let i=0;i<=4;i++){const y=pt+ih*i/4;c.beginPath();c.moveTo(pl,y);c.lineTo(w-pr,y);c.stroke();c.textAlign='right';c.fillText(o.yl?o.yl(max*(1-i/4)):Math.round(max*(1-i/4)),pl-6,y+4)}
 (o.xl||[]).forEach((t,i,a)=>{c.textAlign='center';c.fillText(t,pl+iw*i/(a.length-1),h-5)});
 series.forEach(s=>{const n=s.d.length,pts=s.d.map((v,i)=>[pl+iw*i/(n-1),pt+ih*(1-clamp(v/max,0,1))]);const g=c.createLinearGradient(0,pt,0,pt+ih);g.addColorStop(0,s.c+'66');g.addColorStop(1,s.c+'00');c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.strokeStyle=s.c;c.lineWidth=2;c.lineJoin='round';c.shadowColor=s.c;c.shadowBlur=8;c.stroke();c.shadowBlur=0;c.lineTo(pts[n-1][0],pt+ih);c.lineTo(pts[0][0],pt+ih);c.closePath();c.fillStyle=g;c.fill();const e=pts[n-1];c.beginPath();c.arc(e[0],e[1],4,0,7);c.fillStyle=s.c;c.fill()})}
function barChart(cv,vals,labels,o={}){if(!cv||!cv.isConnected)return;const draw=p=>{const[c,w,h]=fit(cv),mu=css(cv,'--mu')||'#98a2bd',tx=css(cv,'--tx')||'#e4e8f3';c.clearRect(0,0,w,h);const pl=34,pb=24,pt=24,pr=8,iw=w-pl-pr,ih=h-pt-pb,max=o.max||100;c.font=FONT;c.strokeStyle='rgba(128,140,190,.18)';
 for(let i=0;i<=5;i++){const y=pt+ih*i/5;c.beginPath();c.moveTo(pl,y);c.lineTo(w-pr,y);c.stroke();c.fillStyle=mu;c.textAlign='right';c.fillText(Math.round(max*(1-i/5)),pl-6,y+4)}
 const n=vals.length,bw=Math.min(56,iw/n*.58),tops=[];vals.forEach((v,i)=>{const x=pl+iw*(i+.5)/n,bh=ih*v/max*p,y=pt+ih-bh;const g=c.createLinearGradient(0,y,0,pt+ih);g.addColorStop(0,o.c1||'#19d3ff');g.addColorStop(1,o.c2||'#1f4fff');c.fillStyle=g;c.beginPath();c.roundRect?c.roundRect(x-bw/2,y,bw,Math.max(bh,1),[6,6,0,0]):c.rect(x-bw/2,y,bw,bh);c.fill();tops.push([x,y]);c.fillStyle=tx;c.textAlign='center';c.fillText(Math.round(v*p),x,y-6);c.fillStyle=mu;c.fillText(labels[i]||'',x,h-6)});
 if(o.trend&&p===1){c.strokeStyle='#2f9bff';c.lineWidth=2;c.beginPath();c.moveTo(tops[0][0],tops[0][1]-14);c.lineTo(tops[n-1][0],tops[n-1][1]-26);c.stroke();c.beginPath();c.moveTo(tops[n-1][0]+7,tops[n-1][1]-26);c.lineTo(tops[n-1][0]-3,tops[n-1][1]-32);c.lineTo(tops[n-1][0]-3,tops[n-1][1]-20);c.closePath();c.fillStyle='#2f9bff';c.fill()}};
 if(cv._d&&!o.anim){draw(1);return}cv._d=1;let t0;const f=t=>{t0=t0||t;const p=Math.min(1,(t-t0)/600);draw(1-Math.pow(1-p,3));if(p<1&&cv.isConnected)requestAnimationFrame(f)};requestAnimationFrame(f)}
function spark(cv,d,col){if(!cv||!cv.isConnected)return;const[c,w,h]=fit(cv),mx=Math.max(...d),mn=Math.min(...d);c.beginPath();d.forEach((v,i)=>{const x=w*i/(d.length-1),y=h-3-(h-6)*(v-mn)/(mx-mn||1);i?c.lineTo(x,y):c.moveTo(x,y)});c.strokeStyle=col;c.lineWidth=2;c.lineJoin='round';c.shadowColor=col;c.shadowBlur=6;c.stroke()}
