let DOTS=null;const inP=(x,y,p)=>{let c=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])c=!c}return c};
function worldMap(cv,o){if(!DOTS){DOTS=[];for(let la=80;la>=-56;la-=2.2)for(let lo=-170;lo<=180;lo+=2.2)if(POLY.some(p=>inP(lo,la,p)))DOTS.push([lo,la])}
 let stop=false,base,T=[],ctx,W,H,sc,ox,oy;const cols=o.cols||['#ff2d46'];
 const P=p=>[ox+(p[0]+170)*sc,oy+(80-p[1])*sc];
 function setup(){const r=fit(cv);ctx=r[0];W=r[1];H=r[2];sc=Math.min(W/350,H/136);ox=(W-350*sc)/2;oy=(H-136*sc)/2;base=document.createElement('canvas');base.width=cv.width;base.height=cv.height;const b=base.getContext('2d'),d=cv.width/W;b.setTransform(d,0,0,d,0,0);b.fillStyle=css(cv,'--mapdot')||'rgba(120,140,200,.38)';const s=Math.max(1.3,sc*1.5);DOTS.forEach(p=>{const q=P(p);b.fillRect(q[0],q[1],s,s)});T=Array.from({length:o.n||60},(_,i)=>({p:P(pick(DOTS)),c:cols[i%cols.length],s:rnd(0,6),big:Math.random()<.1}))}
 setup();const ro=new ResizeObserver(()=>{if(!stop)setup()});ro.observe(cv.parentElement);
 const loop=t=>{if(stop||!cv.isConnected)return;ctx.clearRect(0,0,W,H);ctx.drawImage(base,0,0,W,H);T.forEach(a=>{const k=((t/1000+a.s)%2)/2,m=a.big?1.9:1;ctx.globalAlpha=1;ctx.fillStyle=a.c;ctx.beginPath();ctx.arc(a.p[0],a.p[1],a.big?3.2:2,0,7);ctx.fill();ctx.globalAlpha=(1-k)*.55;ctx.strokeStyle=a.c;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(a.p[0],a.p[1],3+k*13*m,0,7);ctx.stroke()});ctx.globalAlpha=1;requestAnimationFrame(loop)};requestAnimationFrame(loop);
 vclean.push(()=>{stop=true;ro.disconnect()})}
