let S3;
const ACT0=[['Suspicious Login Attempt','تلاش ورود مشکوک','h'],['Malware Detected','بدافزار شناسایی شد','h'],['Firewall Blocked IP','فایروال یک IP را مسدود کرد','i'],['Port Scan Alert','هشدار اسکن پورت','w'],['System Update Completed','به‌روزرسانی سیستم انجام شد','s']];
const BL={h:['High','بالا'],i:['Info','اطلاعات'],w:['Warning','هشدار'],s:['Success','موفق']};
const walk=(n,a,b,s)=>{const r=[];let x=rnd(a,b);for(let i=0;i<n;i++){x=clamp(x+rnd(-s,s*1.4),a,b);r.push(x)}return r};
function init3(){S3={view:'dashboard',threat:92,sec:98.5,gb:842,users:12800,up:99.9,dn:Array.from({length:20},(_,i)=>200+i*22+rnd(-50,50)),upl:Array.from({length:20},(_,i)=>80+i*12+rnd(-30,30)),acts:ACT0.map((a,i)=>({t:clock(i*214+30),a:[a[0],a[1]],s:a[2]})),sp:[walk(12,40,100,12),walk(12,40,100,12),walk(12,40,100,12),walk(12,40,100,12)],notes:[['New login from unknown device','ورود جدید از دستگاه ناشناس',1],['Firewall rules updated','قوانین فایروال به‌روز شد',1],['Weekly security report is ready','گزارش امنیتی هفتگی آماده است',1]],ctl:{tfa:true,waf:true,rl:true,au:false,geo:false},ips:['203.0.113.7','198.51.100.23'],busy:false}}
const unread=()=>S3.notes.filter(n=>n[2]).length;
